import re, json
def parse_grids(txt):
    lines=txt.splitlines()
    grids=[]; cur=[]
    for ln in lines:
        toks=ln.split()
        if len(toks)>=3 and all(re.fullmatch(r'\d',t) for t in toks):
            cur.append([int(t) for t in toks])
        else:
            if cur: grids.append(cur); cur=[]
    if cur: grids.append(cur)
    return grids
